# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KESİR, ONDALIK VE YÜZDE GÖSTERİMLERİ ARASINDA DÖNÜŞÜM</text>\n  <rect x="25" y="55" width="205" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="127" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Ortak Gösterim Seçimi</text>\n  <text x="127" y="108" text-anchor="middle" font-size="12" fill="#1e3a8a">• Yarım: Sıfır tam onda beş = %50</text>\n  <text x="127" y="132" text-anchor="middle" font-size="12" fill="#1e3a8a">• Çeyrek: Sıfır tam yüzde yirmi beş = %25</text>\n  <text x="127" y="156" text-anchor="middle" font-size="12" fill="#1e3a8a">• Dörtte üç: Sıfır tam yüzde yetmiş beş = %75</text>\n  <text x="127" y="180" text-anchor="middle" font-size="12" fill="#1e3a8a">• Beşte bir: Sıfır tam onda iki = %20</text>\n  <text x="127" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Aynı dilde işlem kolaylığı sağlar</text>\n  <rect x="247" y="55" width="205" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Şerit Modeli (Kalanın Kesri)</text>\n  <rect x="267" y="96" width="165" height="28" fill="#dcfce7" stroke="#16a34a"/>\n  <line x1="300" y1="96" x2="300" y2="124" stroke="#16a34a"/>\n  <line x1="333" y1="96" x2="333" y2="124" stroke="#16a34a"/>\n  <line x1="366" y1="96" x2="366" y2="124" stroke="#16a34a"/>\n  <line x1="399" y1="96" x2="399" y2="124" stroke="#16a34a"/>\n  <text x="350" y="148" text-anchor="middle" font-size="11" fill="#14532d">1. Adım: Bütünün %40\'ı (2 kutu) harcanır.</text>\n  <text x="350" y="170" text-anchor="middle" font-size="11" fill="#14532d">2. Adım: Kalan 3 kutunun üçte biri (1 kutu)</text>\n  <text x="350" y="188" text-anchor="middle" font-size="11" fill="#14532d">daha harcanırsa geriye 2 kutu (%40) kalır.</text>\n  <text x="350" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Görsel temsil hatayı önler</text>\n  <rect x="470" y="55" width="205" height="180" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="572" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Parçadan Bütüne (Ters İşlem)</text>\n  <text x="572" y="108" text-anchor="middle" font-size="11" fill="#713f12">Kalan miktar biliniyorsa:</text>\n  <text x="572" y="132" text-anchor="middle" font-size="11" fill="#713f12">• Kalan parça sayısına bölünür</text>\n  <text x="572" y="150" text-anchor="middle" font-size="11" fill="#713f12">(Birim parça değeri bulunur).</text>\n  <text x="572" y="174" text-anchor="middle" font-size="11" fill="#713f12">• Toplam parça sayısıyla (payda)</text>\n  <text x="572" y="192" text-anchor="middle" font-size="11" fill="#713f12">çarpılarak başlangıç bütünü bulunur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FİNANSAL OKURYAZARLIK VE ÇOK ADIMLI PROBLEM STRATEJİLERİ</text>\n  <rect x="25" y="55" width="310" height="180" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">İndirim, Kâr ve Bütçe Hesapları</text>\n  <text x="180" y="108" text-anchor="middle" font-size="12" fill="#164e63">• Etiket fiyatı 400 TL olan ürüne %25 indirim:</text>\n  <text x="180" y="130" text-anchor="middle" font-size="12" fill="#164e63">1. Yol: 400 × 0,25 = 100 TL → 400 - 100 = 300 TL</text>\n  <text x="180" y="152" text-anchor="middle" font-size="12" fill="#164e63">2. Kısa Yol: %100 - %25 = %75 → 400 × 0,75 = 300 TL</text>\n  <text x="180" y="182" text-anchor="middle" font-size="11" fill="#475569">Ardışık indirimlerde ikinci indirim, birinci</text>\n  <text x="180" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">indirimli satış fiyatı üzerinden hesaplanır!</text>\n  <rect x="365" y="55" width="310" height="180" rx="8" fill="#f3e8ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Tahmin ve Sonuç Kontrolü</text>\n  <text x="520" y="108" text-anchor="middle" font-size="12" fill="#581c87">• Yuvarlama ile Tahmin: 19,85 TL × 4,1 kg</text>\n  <text x="520" y="130" text-anchor="middle" font-size="12" fill="#581c87">Yaklaşık: 20 TL × 4 kg = 80 TL beklenir.</text>\n  <text x="520" y="156" text-anchor="middle" font-size="12" fill="#581c87">• Gerçek Sonuç: 81,385 TL (Tahmine çok yakın).</text>\n  <text x="520" y="184" text-anchor="middle" font-size="11" fill="#475569">Virgül kaydırma hatalarını yakalamak için</text>\n  <text x="520" y="200" text-anchor="middle" font-size="11" font-weight="bold" fill="#6d28d9">işlem öncesi tahmin yapmak çok etkilidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PROBLEM KURMA, KISA YOLLAR VE GENELLEME SÜRECİ (MAT.6.1.7)</text>\n  <rect x="25" y="60" width="145" height="165" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="97" y="85" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. Analiz ve Temsil</text>\n  <text x="97" y="112" text-anchor="middle" font-size="11" fill="#334155">Verilen ve istenen</text>\n  <text x="97" y="130" text-anchor="middle" font-size="11" fill="#334155">nicelikleri belirle;</text>\n  <text x="97" y="148" text-anchor="middle" font-size="11" fill="#334155">şekil veya tablo çiz.</text>\n  <rect x="188" y="60" width="145" height="165" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="260" y="85" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. Strateji ve Çözüm</text>\n  <text x="260" y="112" text-anchor="middle" font-size="11" fill="#334155">Kesir, ondalık veya</text>\n  <text x="260" y="130" text-anchor="middle" font-size="11" fill="#334155">yüzdeyi ortak dile</text>\n  <text x="260" y="148" text-anchor="middle" font-size="11" fill="#334155">çevirip işlemi yap.</text>\n  <rect x="352" y="60" width="145" height="165" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="424" y="85" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">3. Kontrol ve Kısa Yol</text>\n  <text x="424" y="112" text-anchor="middle" font-size="11" fill="#334155">Sonucu tahminle sına;</text>\n  <text x="424" y="130" text-anchor="middle" font-size="11" fill="#334155">daha pratik çözüm</text>\n  <text x="424" y="148" text-anchor="middle" font-size="11" fill="#334155">yollarını değerlendir.</text>\n  <rect x="516" y="60" width="158" height="165" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="595" y="85" text-anchor="middle" font-size="12" font-weight="bold" fill="#be185d">4. Genelleme ve Kurma</text>\n  <text x="595" y="112" text-anchor="middle" font-size="11" fill="#334155">Stratejiyi yeni bir</text>\n  <text x="595" y="130" text-anchor="middle" font-size="11" fill="#334155">probleme uyarla ve</text>\n  <text x="595" y="148" text-anchor="middle" font-size="11" fill="#334155">özgün problem kur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
